import{_ as r,o as t,c as o,a4 as e}from"./chunks/framework.B-3VpRq4.js";const p=JSON.parse('{"title":"战队介绍","description":"","frontmatter":{},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md"}'),n={name:"about/index.md"};function i(s,a,l,h,d,c){return t(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="战队介绍" tabindex="-1">战队介绍 <a class="header-anchor" href="#战队介绍" aria-label="Permalink to &quot;战队介绍&quot;">​</a></h1><h2 id="我们是谁" tabindex="-1">我们是谁 <a class="header-anchor" href="#我们是谁" aria-label="Permalink to &quot;我们是谁&quot;">​</a></h2><p><strong>ARK（云龙）战队</strong> 是徐州工程学院的 RoboMaster 机甲大师参赛战队。</p><blockquote><p>&quot;ARK&quot; — 方舟，承载梦想，驶向星辰大海。 &quot;云龙&quot; — 取自徐州云龙山/云龙湖，根植彭城大地，志在九天云霄。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">我们是初创战队</p><p>ARK 是一支全新组建的战队，正在为 RM2027 赛季积极备赛。虽然我们是新队伍，但我们有热情、有冲劲、有不服输的精神！</p></div><h2 id="战队文化" tabindex="-1">战队文化 <a class="header-anchor" href="#战队文化" aria-label="Permalink to &quot;战队文化&quot;">​</a></h2><h3 id="🎯-使命" tabindex="-1">🎯 使命 <a class="header-anchor" href="#🎯-使命" aria-label="Permalink to &quot;🎯 使命&quot;">​</a></h3><p>以赛促学，以赛促创。通过 RoboMaster 比赛，培养队员在机械设计、嵌入式系统、计算机视觉、自动化控制等领域的综合工程能力。</p><h3 id="🏆-精神" tabindex="-1">🏆 精神 <a class="header-anchor" href="#🏆-精神" aria-label="Permalink to &quot;🏆 精神&quot;">​</a></h3><ul><li><strong>极致</strong>：追求每一个细节的完美</li><li><strong>竞争</strong>：在赛场上证明自己</li><li><strong>疯狂</strong>：为热爱全力以赴</li></ul><h3 id="🤝-传承" tabindex="-1">🤝 传承 <a class="header-anchor" href="#🤝-传承" aria-label="Permalink to &quot;🤝 传承&quot;">​</a></h3><p>我们相信：<strong>&quot;把机器人造出来，把能力练出来，把经验传下去&quot;</strong></p><h2 id="战队架构" tabindex="-1">战队架构 <a class="header-anchor" href="#战队架构" aria-label="Permalink to &quot;战队架构&quot;">​</a></h2><p>ARK 战队按技术方向分为以下组别：</p><div class="rm-card"><h3 id="🛠️-机械组" tabindex="-1">🛠️ 机械组 <a class="header-anchor" href="#🛠️-机械组" aria-label="Permalink to &quot;🛠️ 机械组&quot;">​</a></h3><p>负责机器人结构设计、有限元分析、加工装配。使用 <strong>SolidWorks</strong> 进行 3D 建模，涵盖底盘、云台、发射机构等核心结构。</p><p><strong>核心技能</strong>：SolidWorks、材料力学、机械原理、3D 打印/CNC 加工</p></div><div class="rm-card"><h3 id="⚡-电控组" tabindex="-1">⚡ 电控组 <a class="header-anchor" href="#⚡-电控组" aria-label="Permalink to &quot;⚡ 电控组&quot;">​</a></h3><p>负责嵌入式系统开发、电机控制、传感器数据采集、通信协议实现。主控使用 <strong>STM32</strong> 系列，驱动 DJI M3508/M2006/GM6020 等电机。</p><p><strong>核心技能</strong>：STM32、嵌入式 C、PID 控制、CAN 通信</p></div><div class="rm-card"><h3 id="👁️-视觉组" tabindex="-1">👁️ 视觉组 <a class="header-anchor" href="#👁️-视觉组" aria-label="Permalink to &quot;👁️ 视觉组&quot;">​</a></h3><p>负责目标检测、自动瞄准、定位导航。使用 <strong>OpenCV</strong> + <strong>YOLO</strong> 系列算法，实现对装甲板的精准识别和自动瞄准。</p><p><strong>核心技能</strong>：OpenCV、YOLOv8+、C++/Python、Linux</p></div><div class="rm-card"><h3 id="🧠-算法组" tabindex="-1">🧠 算法组 <a class="header-anchor" href="#🧠-算法组" aria-label="Permalink to &quot;🧠 算法组&quot;">​</a></h3><p>负责路径规划、决策算法、运动控制算法。使用 <strong>ROS2</strong> + <strong>C++/Python</strong>，涵盖哨兵全自动导航、仿真模拟等。</p><p><strong>核心技能</strong>：ROS2、路径规划、SLAM、卡尔曼滤波</p></div><hr><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><ul><li>📧 邮箱：待填写</li><li>🐙 Gitee：<a href="https://gitee.com/yunlongark/ark-robomaster" target="_blank" rel="noreferrer">ARK-RoboMaster</a></li><li>📍 地址：徐州工程学院</li></ul><hr><p><em>期待 RM2027 赛季，ARK 云龙，蓄势待发！🚀</em></p>',23)])])}const b=r(n,[["render",i]]);export{p as __pageData,b as default};
